-- Target schema for the native Flutter/Drift implementation.
-- This file is executable SQLite DDL, not the HTML application's storage engine.
PRAGMA foreign_keys = ON;
CREATE TABLE workspaces (id TEXT PRIMARY KEY, name TEXT NOT NULL, schema_version INTEGER NOT NULL CHECK(schema_version=1));
CREATE TABLE devices (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), public_key BLOB NOT NULL, revoked_at TEXT, UNIQUE(id,workspace_id));
CREATE TABLE pupils (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), name TEXT NOT NULL CHECK(length(trim(name))>0), archived_at TEXT, deleted_at TEXT, revision INTEGER NOT NULL DEFAULT 1, UNIQUE(id,workspace_id));
CREATE TABLE situations (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), observed_date TEXT NOT NULL, observed_time TEXT, context_code TEXT CHECK(context_code IN ('before','during','after','break')), narrative TEXT NOT NULL DEFAULT '', captured_at_utc TEXT NOT NULL, deleted_at TEXT, revision INTEGER NOT NULL DEFAULT 1, UNIQUE(id,workspace_id));
CREATE TABLE participants (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), situation_id TEXT NOT NULL, pupil_id TEXT, name_snapshot TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'participant', FOREIGN KEY(situation_id,workspace_id) REFERENCES situations(id,workspace_id), FOREIGN KEY(pupil_id,workspace_id) REFERENCES pupils(id,workspace_id));
CREATE TABLE goals (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, pupil_id TEXT NOT NULL, text TEXT NOT NULL, criterion TEXT NOT NULL DEFAULT '', pupil_perspective TEXT NOT NULL DEFAULT '', next_step TEXT NOT NULL DEFAULT '', status TEXT NOT NULL CHECK(status IN ('active','reached','closed')), deadline_date TEXT, review_date TEXT, deleted_at TEXT, revision INTEGER NOT NULL DEFAULT 1, FOREIGN KEY(pupil_id,workspace_id) REFERENCES pupils(id,workspace_id), UNIQUE(id,pupil_id,workspace_id));
CREATE TABLE observations (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, situation_id TEXT NOT NULL, pupil_id TEXT NOT NULL, narrative TEXT NOT NULL DEFAULT '', source_kind TEXT NOT NULL CHECK(source_kind IN ('own','reported','interpretation')), support TEXT NOT NULL DEFAULT '', documentation_status TEXT NOT NULL CHECK(documentation_status IN ('saved','needs_completion')), goal_id TEXT, goal_text_snapshot TEXT, deleted_at TEXT, revision INTEGER NOT NULL DEFAULT 1, FOREIGN KEY(situation_id,workspace_id) REFERENCES situations(id,workspace_id), FOREIGN KEY(pupil_id,workspace_id) REFERENCES pupils(id,workspace_id), FOREIGN KEY(goal_id,pupil_id,workspace_id) REFERENCES goals(id,pupil_id,workspace_id));
CREATE TABLE observation_tags (id TEXT PRIMARY KEY, observation_id TEXT NOT NULL REFERENCES observations(id), text_snapshot TEXT NOT NULL, tone TEXT CHECK(tone IN ('positive','negative')));
CREATE TABLE goal_reviews (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, goal_id TEXT NOT NULL, pupil_id TEXT NOT NULL, reviewed_date TEXT NOT NULL, outcome TEXT NOT NULL CHECK(outcome IN ('continue','reached','closed','reopen')), note TEXT NOT NULL DEFAULT '', next_step TEXT NOT NULL DEFAULT '', next_review_date TEXT, FOREIGN KEY(goal_id,pupil_id,workspace_id) REFERENCES goals(id,pupil_id,workspace_id));
CREATE TABLE tasks (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), pupil_id TEXT, kind TEXT NOT NULL CHECK(kind IN ('homework','organization')), title TEXT NOT NULL, due_date TEXT, status TEXT NOT NULL CHECK(status IN ('open','partial','done','cancelled')), delivery TEXT CHECK(delivery IN ('unknown','submitted','missing','absent')), deleted_at TEXT, revision INTEGER NOT NULL DEFAULT 1, FOREIGN KEY(pupil_id,workspace_id) REFERENCES pupils(id,workspace_id), UNIQUE(id,workspace_id));
CREATE TABLE task_items (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, task_id TEXT NOT NULL, text TEXT NOT NULL, position TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('open','partial','done','cancelled')), deleted_at TEXT, revision INTEGER NOT NULL DEFAULT 1, FOREIGN KEY(task_id,workspace_id) REFERENCES tasks(id,workspace_id), UNIQUE(id,task_id));
CREATE TABLE task_feedback (id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(id), item_id TEXT, observed_date TEXT NOT NULL, note TEXT NOT NULL DEFAULT '', status TEXT CHECK(status IN ('open','partial','done','cancelled')), delivery TEXT CHECK(delivery IN ('unknown','submitted','missing','absent')), deleted_at TEXT, FOREIGN KEY(item_id,task_id) REFERENCES task_items(id,task_id));
CREATE TABLE reminders (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), task_id TEXT NOT NULL, due_at_utc TEXT NOT NULL, timezone TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('planned','done','cancelled')), native_notification_id TEXT, FOREIGN KEY(task_id,workspace_id) REFERENCES tasks(id,workspace_id));
CREATE TABLE drafts (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), device_id TEXT NOT NULL, editor_kind TEXT NOT NULL, entity_id TEXT, base_revision INTEGER, payload TEXT NOT NULL CHECK(json_valid(payload)), updated_at_utc TEXT NOT NULL, FOREIGN KEY(device_id,workspace_id) REFERENCES devices(id,workspace_id));
CREATE TABLE revisions (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), entity_kind TEXT NOT NULL, entity_id TEXT NOT NULL, base_revision INTEGER, payload TEXT NOT NULL CHECK(json_valid(payload)), captured_at_utc TEXT NOT NULL, device_id TEXT NOT NULL, FOREIGN KEY(device_id,workspace_id) REFERENCES devices(id,workspace_id));
CREATE TABLE operations (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), device_id TEXT NOT NULL, sequence INTEGER NOT NULL CHECK(sequence>0), protocol_version INTEGER NOT NULL CHECK(protocol_version=1), payload TEXT NOT NULL CHECK(json_valid(payload)), FOREIGN KEY(device_id,workspace_id) REFERENCES devices(id,workspace_id), UNIQUE(device_id,sequence));
CREATE TABLE outbox (operation_id TEXT PRIMARY KEY REFERENCES operations(id));
CREATE TABLE receipts (workspace_id TEXT NOT NULL REFERENCES workspaces(id), peer_id TEXT NOT NULL, origin_id TEXT NOT NULL, contiguous_sequence INTEGER NOT NULL CHECK(contiguous_sequence>=0), FOREIGN KEY(peer_id,workspace_id) REFERENCES devices(id,workspace_id), FOREIGN KEY(origin_id,workspace_id) REFERENCES devices(id,workspace_id), PRIMARY KEY(peer_id,origin_id));
CREATE TABLE conflicts (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), entity_kind TEXT NOT NULL, entity_id TEXT NOT NULL, base_payload TEXT CHECK(json_valid(base_payload)), current_payload TEXT NOT NULL CHECK(json_valid(current_payload)), incoming_payload TEXT NOT NULL CHECK(json_valid(incoming_payload)), resolution TEXT CHECK(json_valid(resolution)), resolved_at_utc TEXT);
CREATE INDEX observations_pupil_date ON observations(pupil_id,situation_id);
CREATE INDEX tasks_due ON tasks(due_date,status);
CREATE INDEX goals_review ON goals(review_date,status);
CREATE INDEX operations_origin ON operations(device_id,sequence);
